import csv

with open('table.csv', newline='') as f:
    rows = list(csv.reader(f))

header = rows[0]
data = rows[1:]
ncols = len(header)

escaped = [[c.replace('|', '\\|') for c in row] for row in [header] + data]

def is_num(s):
    try:
        float(s)
        return True
    except ValueError:
        return False

numeric = []
for j in range(ncols):
    vals = [row[j] for row in data]
    numeric.append(all(is_num(v) for v in vals))

widths = []
for j in range(ncols):
    widths.append(max([3] + [len(r[j]) for r in escaped]))

lines = []
cells = []
for j in range(ncols):
    if numeric[j]:
        cells.append(escaped[0][j].rjust(widths[j]))
    else:
        cells.append(escaped[0][j].ljust(widths[j]))
lines.append('| ' + ' | '.join(cells) + ' |')

sep = []
for j in range(ncols):
    if numeric[j]:
        sep.append('-' * (widths[j] - 1) + ':')
    else:
        sep.append('-' * widths[j])
lines.append('| ' + ' | '.join(sep) + ' |')

for row in escaped[1:]:
    cells = []
    for j in range(ncols):
        if numeric[j]:
            cells.append(row[j].rjust(widths[j]))
        else:
            cells.append(row[j].ljust(widths[j]))
    lines.append('| ' + ' | '.join(cells) + ' |')

with open('table.md', 'w') as f:
    f.write('\n'.join(lines) + '\n')
